text(await tools.exec_command({cmd:"Get-Content -LiteralPath ./packet/SHA256SUMS","max_output_tokens":12000}));
text(await tools.exec_command({cmd:"Get-ChildItem -LiteralPath ./output -Force -ErrorAction SilentlyContinue | Select-Object Name,Length","max_output_tokens":2000}));
text(ALL_TOOLS.filter(x=>/file|python|directory|terminal|command/i.test(x.name+" "+x.description)).map(x=>({name:x.name,description:x.description.slice(0,140)})).slice(0,100));

text(await tools.exec_command({cmd:"$ErrorActionPreference='Stop'
New-Item -ItemType Directory -Path ./output -Force | Out-Null
$packetRoot=(Resolve-Path -LiteralPath ./packet).Path
$checks=@(foreach($entry in Get-Content -LiteralPath ./packet/SHA256SUMS){
 if($entry -notmatch '^([0-9a-fA-F]{64})\s+\*?(.+)$'){throw 'Invalid SHA256SUMS entry'}
 $expected=$Matches[1].ToLowerInvariant()
 $relative=$Matches[2]
 $target=[IO.Path]::GetFullPath((Join-Path $packetRoot $relative))
 if(-not $target.StartsWith($packetRoot+[IO.Path]::DirectorySeparatorChar)){throw 'Hash path escapes packet'}
 $actual=if(Test-Path -LiteralPath $target -PathType Leaf){(Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash.ToLowerInvariant()}else{$null}
 [pscustomobject]@{path=$relative;expected_sha256=$expected;actual_sha256=$actual;status=if($null -eq $actual){'MISSING'}elseif($actual -eq $expected){'MATCH'}else{'MISMATCH'}}
})
$result=[ordered]@{run_id='RUN-W3';verified_at_utc=[DateTime]::UtcNow.ToString('o');manifest_sha256=(Get-FileHash -LiteralPath ./packet/SHA256SUMS -Algorithm SHA256).Hash.ToLowerInvariant();checked_count=$checks.Count;match_count=@($checks|Where-Object status -eq 'MATCH').Count;issues=@($checks|Where-Object status -ne 'MATCH');files=$checks}
$result|ConvertTo-Json -Depth 6|Set-Content -LiteralPath ./output/packet_integrity.json -Encoding UTF8
$result|Select-Object run_id,verified_at_utc,manifest_sha256,checked_count,match_count,issues|ConvertTo-Json -Depth 6","max_output_tokens":3000}));
text(await tools.exec_command({cmd:"Get-Content -LiteralPath ./packet/RUN_MANIFEST.md,./packet/ALIASES.json,./packet/CONTROL_FACTS.md,./packet/W3_MEASUREMENT_SCOPE.md","max_output_tokens":14000}));
text(await tools.exec_command({cmd:"Get-Content -LiteralPath ./packet/OBSERVER_PROTOCOL.md,./packet/METRICS_DEFINITIONS.md,./packet/EVENT_TAXONOMY.md,./packet/MEASUREMENT_INTEGRITY_RULES.md","max_output_tokens":20000}));

